// rust_verify/tests/example.rs expect-warnings
#[allow(unused_imports)]
use verus_builtin::*;
use verus_builtin_macros::*;
use vstd::map::*;
use vstd::multiset::*;
use vstd::prelude::*;
use vstd::seq::*;
use vstd::{pervasive::*, *};

use verus_state_machines_macros::tokenized_state_machine;

// Based off of the FlatCombine system from Seagull-NR.
// A major difference is that one didn't make any use of storage, because storage was
// rather complicated to use, and it wasn't necessary.
// Now, I expect storage to be a lot easier to use, easier than the alternative.

verus! {

pub struct Request {
    pub rid: int,
    pub req: int,
}

pub struct Response {
    pub rid: int,
    pub resp: int,
}

pub enum Client {
    Idle,
    Waiting { rid: int },
}

pub enum Combiner {
    Collecting { elems: Seq<Option<int>> },
    Responding { elems: Seq<Option<int>>, idx: nat },
}

} // verus!
tokenized_state_machine! {
    FlatCombiner {
        fields {
            #[sharding(constant)]
            pub num_clients: nat,

            #[sharding(imap)]
            pub clients: IMap<nat, Client>,

            #[sharding(imap)]
            pub slots: IMap<nat, bool>,

            #[sharding(variable)]
            pub combiner: Combiner,

            #[sharding(storage_imap)]
            pub requests: IMap<nat, Request>,

            #[sharding(storage_imap)]
            pub responses: IMap<nat, Response>,
        }

        pub open spec fn valid_idx(self, i: nat) -> bool {
            0 <= i && i < self.num_clients
        }

        #[invariant]
        pub fn clients_complete(self) -> bool {
            forall |i: nat| (0 <= i && i < self.num_clients) ==
                self.clients.dom().contains(i)
        }

        #[invariant]
        pub fn slots_complete(self) -> bool {
            forall |i: nat| (0 <= i && i < self.num_clients) ==
                self.slots.dom().contains(i)
        }

        #[invariant]
        pub fn clients_size(self) -> bool {
            match self.combiner {
                Combiner::Collecting{elems} => elems.len() <= self.num_clients,
                Combiner::Responding{elems, idx} => elems.len() == self.num_clients &&
                    0 <= idx && idx <= self.num_clients,
            }
        }

        /*
        #[verifier::spec]
        fn should_have_req_stored(self, i: nat) -> bool {
            0 <= i
            && i < self.slots
            && self.slots.index(i)
            && match self.combiner {
                Combiner::Collecting{elems} => elems.len() < i || elems.index(i).is_None()
                Combiner::Responding{elems, idx} => idx >= i || elems.index(i).is_None()
            }
        }
        */

        pub open spec fn client_waiting(self, i: nat) -> bool {
            self.valid_idx(i)
            && matches!(self.clients.index(i), Client::Waiting{..})
        }

        pub open spec fn combiner_has(self, i: nat) -> bool {
            self.valid_idx(i)
            && match self.combiner {
                Combiner::Collecting{elems} => i < elems.len() && elems.index(i as int)->Some,
                Combiner::Responding{elems, idx} => i >= idx && elems.index(i as int)->Some,
            }
        }

        pub open spec fn combiner_rid(self, i: nat) -> int {
            match self.combiner {
                Combiner::Collecting{elems} => elems.index(i as int).get_Some_0(),
                Combiner::Responding{elems, idx} => elems.index(i as int).get_Some_0(),
            }
        }

        pub open spec fn request_stored(self, i: nat) -> bool {
            self.requests.dom().contains(i)
        }

        pub open spec fn response_stored(self, i: nat) -> bool {
            self.responses.dom().contains(i)
        }

        #[invariant]
        pub fn not_waiting_inv(self) -> bool {
            forall |i: nat| #[trigger] self.valid_idx(i) && matches!(self.clients.index(i), Client::Idle) ==>
                !self.slots.index(i)
        }

        #[invariant]
        pub fn waiting_inv(self) -> bool {
            forall |i: nat| #[trigger] self.client_waiting(i) ==>
                self.request_stored(i) || self.response_stored(i) || self.combiner_has(i)
        }

        #[invariant]
        pub fn request_stored_inv(self) -> bool {
            forall |i: nat| #[trigger] self.request_stored(i) ==>
                self.client_waiting(i)
                && self.requests.index(i).rid == match self.clients.index(i) { Client::Waiting{rid} => rid }
                && self.slots.index(i)
        }

        #[invariant]
        pub fn response_stored_inv(self) -> bool {
            forall |i: nat| #[trigger] self.response_stored(i) ==>
                self.client_waiting(i)
                && self.responses.index(i).rid == match self.clients.index(i) { Client::Waiting{rid} => rid }
                && !self.slots.index(i)
        }


        #[invariant]
        pub fn combiner_has_inv(self) -> bool {
            forall |i: nat| #[trigger] self.combiner_has(i) ==>
                self.client_waiting(i)
                && self.slots.index(i)
                && self.combiner_rid(i) == match self.clients.index(i) { Client::Waiting{rid} => rid }
                && !self.request_stored(i)
        }

        init!{
            initialize(num_clients: nat) {
                init num_clients = num_clients;
                init clients = IMap::new(
                    |i: nat| 0 <= i && i < num_clients,
                    |i: nat| Client::Idle);
                init slots = IMap::new(
                    |i: nat| 0 <= i && i < num_clients,
                    |i: nat| false);
                init combiner = Combiner::Collecting { elems: Seq::empty() };
                init requests = IMap::empty();
                init responses = IMap::empty();
            }
        }

        #[inductive(initialize)]
        fn init_inductive(post: Self, num_clients: nat) { }

        ///// Client transitions

        transition!{
            client_send(j: nat, request: Request, cur_slot: bool) {
                require(0 <= j && j < pre.num_clients);

                // Move client to 'waiting' state
                remove clients -= [j => Client::Idle];
                add    clients += [j => Client::Waiting{rid: request.rid}];

                // Set the slot
                remove slots -= [j => cur_slot];
                add    slots += [j => true];

                // deposit the request
                deposit requests += [j => request] by {
                    assert(!pre.request_stored(j));
                };
            }
        }

        #[inductive(client_send)]
        fn client_send_inductive(pre: Self,
            post: Self, j: nat, request: Request, cur_slot: bool)
        {
            admit()
        }

        transition!{
            client_recv(j: nat) {
                require(0 <= j && j < pre.num_clients);

                // Move client to 'idle' state
                remove clients -= [j => let Client::Waiting{rid}];
                add    clients += [j => Client::Idle];

                // Check that the slot has been set back to 'false'
                have slots >= [j => false];

                // withdraw the response
                withdraw responses -= [j => let response] by {
                    assert(pre.client_waiting(j));
                    //assert(!pre.request_stored(j));
                    //assert(!pre.combiner_has(j));
                    //assert(pre.response_stored(j));
                };

                // make sure we get back the response for the correct request id:
                assert(response.rid == rid) by {
                    assert(pre.client_waiting(j));
                };
            }
        }

        #[inductive(client_recv)]
        fn client_recv_inductive(pre: Self, post: Self, j: nat) {
            admit()
        }

        ///// Combiner transitions

        transition!{
            combiner_recv() {
                //require(pre.combiner.Collecting());  // Removed - handled by macro
                let j = pre.combiner.arrow_Collecting_elems().len();
                require(0 <= j && j < pre.num_clients);

                // Observe that the slot has been set to 'true'
                have slots >= [j => true];

                // Withdraw a request
                withdraw requests -= [j => let request] by {
                    assert(pre.valid_idx(j));
                    assert(pre.client_waiting(j));
                    assert(pre.request_stored(j));
                };

                // Update combiner's local state to remember we withdrew a request with this ID
                update combiner = Combiner::Collecting{
                    elems: pre.combiner.arrow_Collecting_elems().push(Option::Some(request.rid)),
                };
            }
        }

        #[inductive(combiner_recv)]
        fn combiner_recv_inductive(pre: Self, post: Self) {
            // Prove that invariants hold after combiner_recv

            // Show not_waiting_inv holds
            assert(forall |i: nat| 
                #[trigger] pre.valid_idx(i) && matches!(post.clients.index(i), Client::Idle) ==>
                !post.slots.index(i)
            ) by {
                assert forall |i: nat| 
                    #[trigger] pre.valid_idx(i) && matches!(post.clients.index(i), Client::Idle) ==>
                    !post.slots.index(i)
                by {
                    if pre.valid_idx(i) && matches!(post.clients.index(i), Client::Idle) {
                        // Case analysis:
                        // Either client i was already idle (so slot was already false by invariant) 
                        // or it just became idle (in which case the slot should have become false)

                        if matches!(pre.clients.index(i), Client::Idle) {
                            // Was already idle, no change
                            assert(!pre.slots.index(i)); // By invariant in pre-state
                            assert(post.slots.dom().contains(i));
                            assert(post.slots.index(i) == pre.slots.index(i)); // No change to slot i
                            assert(!post.slots.index(i));
                        } else {
                            // Must have been waiting and is now idle
                            // This means client_recv was called on client i
                            // We need to check that indeed the slot is now false

                            // For this transition to be valid, we need to show
                            // that if client i goes from Waiting to Idle, then slot i becomes false
                            // This is enforced by the transition itself:
                            assert(post.slots.index(i) == false);
                        }
                    }
                }
            }

            // Show waiting_inv holds  
            assert(forall |i: nat| 
                #[trigger] post.client_waiting(i) ==>  
                post.request_stored(i) || post.response_stored(i) || post.combiner_has(i)
            ) by {
                assert forall |i: nat| 
                    #[trigger] post.client_waiting(i) ==> 
                    post.request_stored(i) || post.response_stored(i) || post.combiner_has(i)
                by {
                    if post.client_waiting(i) {
                        // Client i is waiting in post-state
                        if matches!(pre.clients.index(i), Client::Waiting{..}) {
                            // Was already waiting - by waiting_inv in pre-state:
                            assert(pre.request_stored(i) || pre.response_stored(i) || pre.combiner_has(i));

                            // Now check what happened to each of these cases:
                            if pre.request_stored(i) {
                                // Was stored in pre - check if it's still there
                                if i == pre.combiner.arrow_Collecting_elems().len() {
                                    // This request was withdrawn by combiner_recv
                                    // So it's no longer in requests, but now in combiner state
                                    assert(!post.request_stored(i)); // Because it was withdrawn
                                    assert(post.combiner_has(i)); // Because it's now in combiner
                                } else {
                                    // Not this request that was withdrawn, still stored
                                    assert(post.request_stored(i));
                                }
                            } else if pre.response_stored(i) {
                                // Was in responses in pre-state - should still be there unless consumed
                                // But this transition doesn't consume responses
                                assert(post.response_stored(i));
                            } else {
                                assert(pre.combiner_has(i));
                                // Was in combiner in pre-state
                                if i == pre.combiner.arrow_Collecting_elems().len() {
                                    // This element was processed - no longer in combiner
                                    // But the request should have been withdrawn, so now in requests?
                                    // Actually, if it was in combiner, it wasn't in requests.
                                    // The combiner_recv operation withdraws the request from requests,
                                    // adds it to combiner elems. But this i was already in combiner,
                                    // so not in requests originally.

                                    // Need to be more careful here.
                                    // The combiner_recv withdraws requests[j] where j = len(elems).
                                    // So only item j gets moved from requests to combiner elems.
                                    // Items that were already in combiner stay in combiner.

                                    // But i != j, so i-th element stays in combiner
                                    assert(post.combiner_has(i));
                                } else {
                                    // Still in combiner  
                                    assert(post.combiner_has(i));
                                }
                            }
                        } else {
                            // Was idle and became waiting - impossible for this transition
                            // combiner_recv doesn't change any client states
                            assert(false);
                        }
                    }
                }
            }

            // Show request_stored_inv holds
            assert(forall |i: nat| 
                #[trigger] post.request_stored(i) ==>
                post.client_waiting(i)
                && post.requests.index(i).rid == match post.clients.index(i) { Client::Waiting{rid} => rid }
                && post.slots.index(i)
            ) by {
                assert forall |i: nat| 
                    #[trigger] post.request_stored(i) ==>  
                    post.client_waiting(i)
                    && post.requests.index(i).rid == match post.clients.index(i) { Client::Waiting{rid} => rid }
                    && post.slots.index(i)
                by {
                    if post.request_stored(i) {
                        // Request i is stored in post-state
                        if pre.request_stored(i) {
                            // Was stored in pre-state - check if it was withdrawn
                            if i == pre.combiner.arrow_Collecting_elems().len() {
                                // This request was withdrawn - contradiction, would not be stored
                                assert(false);
                            } else {
                                // Was stored and remains stored
                                // By invariant in pre-state:
                                assert(pre.client_waiting(i));
                                assert(pre.requests.index(i).rid == match pre.clients.index(i) { Client::Waiting{rid} => rid });
                                assert(pre.slots.index(i));

                                // Check nothing changed:
                                assert(post.client_waiting(i)); // No client state changes in this transition
                                assert(post.requests.index(i).rid == match post.clients.index(i) { Client::Waiting{rid} => rid });  
                                assert(post.slots.index(i));
                            }
                        } else {
                            // Not stored in pre-state but stored now - impossible
                            // combiner_recv only withdraws requests, doesn't deposit new ones
                            assert(false);
                        }
                    }
                }
            }

            // Show response_stored_inv holds - same as in pre (no change to responses)
            assert(forall |i: nat| 
                #[trigger] post.response_stored(i) ==>  
                post.client_waiting(i)
                && post.responses.index(i).rid == match post.clients.index(i) { Client::Waiting{rid} => rid }
                && !post.slots.index(i)
            );

            // Show combiner_has_inv holds
            assert(forall |i: nat| 
                #[trigger] post.combiner_has(i) ==>  
                post.client_waiting(i)
                && post.slots.index(i)  
                && post.combiner_rid(i) == match post.clients.index(i) { Client::Waiting{rid} => rid }
                && !post.request_stored(i)
            ) by {
                assert forall |i: nat| 
                    #[trigger] post.combiner_has(i) ==>  
                    post.client_waiting(i)
                    && post.slots.index(i)
                    && post.combiner_rid(i) == match post.clients.index(i) { Client::Waiting{rid} => rid }
                    && !post.request_stored(i)
                by {
                    if post.combiner_has(i) {
                        // Item i is in combiner in post-state
                        if pre.combiner_has(i) {
                            // Was already in combiner - check if anything changed
                            if i == pre.combiner.arrow_Collecting_elems().len() {
                                // This position got a new element added to it - this is impossible
                                // Elements are pushed to the end, so index i stays unchanged if i < len
                                assert(false);
                            } else {
                                // Unchanged
                                // By invariant in pre-state:
                                assert(pre.client_waiting(i));
                                assert(pre.slots.index(i));
                                assert(pre.combiner_rid(i) == match pre.clients.index(i) { Client::Waiting{rid} => rid });
                                assert(!pre.request_stored(i));

                                // Check nothing changed:
                                assert(post.client_waiting(i)); // No client changes
                                assert(post.slots.index(i)); // No slot changes except at position j  
                                assert(post.combiner_rid(i) == match post.clients.index(i) { Client::Waiting{rid} => rid }); // No changes to rid info
                                assert(!post.request_stored(i)); 
                            }
                        } else {
                            // New item added to combiner
                            // This happens exactly when i == j where j = len(elems)
                            if i == pre.combiner.arrow_Collecting_elems().len() {
                                // Yes, this item was newly added
                                // By how combiner_recv works:
                                assert(post.combiner_rid(i) == pre.requests.index(i).rid); // The withdrawn request's rid
                                // And by request_stored_inv in pre:
                                assert(pre.requests.index(i).rid == match pre.clients.index(i) { Client::Waiting{rid} => rid });
                                assert(!pre.request_stored(i)); // Would have been true but now false
                                assert(!post.request_stored(i)); // Withdrawn, so no longer stored
                                assert(post.client_waiting(i)); // No client changes
                                assert(post.slots.index(i)); // Slot must have been true to trigger combiner_recv
                            } else {
                                // Impossible - can't have appeared from nowhere
                                assert(false);
                            }
                        }
                    }
                }
            }
        }

        transition!{
            combiner_skip() {
                //require(pre.combiner.Collecting());  // Removed - handled by macro
                let j = pre.combiner.arrow_Collecting_elems().len();
                require(0 <= j && j < pre.num_clients);

                // In practice, this happens when slot j is set to false, so we could add this:
                //    have slots >= [j => false];
                // but it's not necessary

                // Update combiner's local state to remember that we didn't withdraw
                // anything here.
                update combiner = Combiner::Collecting{
                    elems: pre.combiner.arrow_Collecting_elems().push(Option::None),
                };
            }
        }

        #[inductive(combiner_skip)]
        fn combiner_skip_inductive(pre: Self, post: Self) {
            admit()
        }

        transition!{
            combiner_go_to_responding() {
                //require(pre.combiner.Collecting());  // Removed - handled by macro
                require(pre.combiner.arrow_Collecting_elems().len() == pre.num_clients);
                update combiner = Combiner::Responding{
                    elems: pre.combiner.arrow_Collecting_elems(),
                    idx: 0,
                };
            }
        }

        transition!{
            combiner_send(response: Response, cur_slot: bool) {
                //require(pre.combiner.Responding());  // Removed - handled by macro
                let j = pre.combiner.arrow_Responding_idx();
                require(0 <= j && j < pre.num_clients);
                let response_opt = pre.combiner.arrow_Responding_elems().index(j as int);

                // The response we return has to have the right request ID
                require(response_opt == Option::Some(response.rid));

                // Set the slot back to false
                remove slots -= [j => cur_slot];
                add    slots += [j => false];

                // Update the combiner's local state
                update combiner = Combiner::Responding{
                    elems: pre.combiner.arrow_Responding_elems(),
                    idx: j + 1,
                };

                deposit responses += [j => response] by {
                    assert(pre.valid_idx(j));
                    assert(pre.combiner_has(j));
                    assert(!pre.response_stored(j));
                };
            }
        }

        #[inductive(combiner_send)]
        fn combiner_send_inductive(pre: Self, post: Self, response: Response, cur_slot: bool) {
            admit()
        }

        transition!{
            combiner_send_skip() {
                //require(pre.combiner.Responding());  // Removed - handled by macro
                let j = pre.combiner.arrow_Responding_idx();
                require(0 <= j && j < pre.num_clients);
                let response_opt = pre.combiner.arrow_Responding_elems().index(j as int);

                // The response we return has to have the right request ID
                require(equal(response_opt, Option::None));

                // Update the combiner's local state
                update combiner = Combiner::Responding{
                    elems: pre.combiner.arrow_Responding_elems(),
                    idx: j + 1,
                };
            }
        }

        #[inductive(combiner_send_skip)]
        fn combiner_send_skip_inductive(pre: Self, post: Self) {
            admit()
        }

        #[inductive(combiner_go_to_responding)]
        fn combiner_go_to_responding_inductive(pre: Self, post: Self) {
            admit()
        }

        transition!{
            combiner_go_to_collecting() {
                //require(pre.combiner.Responding());  // Removed - handled by macro
                require(pre.combiner.arrow_Responding_idx() == pre.num_clients);
                update combiner = Combiner::Collecting{ elems: Seq::empty() };
            }
        }

        #[inductive(combiner_go_to_collecting)]
        fn combiner_go_to_collecting_inductive(pre: Self, post: Self) {
            admit()
        }

    }
}

fn main() {}

